HRCW=["Risk of a person falling more than 2 metres (in some jurisdictions 3 metres)","Work on a telecommunication tower","Demolition of load-bearing structure","Likely to involve disturbing asbestos","Temporary load-bearing support for structural alterations or repairs","Work in or near a confined space","Work in or near a shaft or trench deeper than 1.5 m or a tunnel","Use of explosives","Work on or near pressurised gas mains or piping","Work on or near chemical, fuel or refrigerant lines","Work on or near energised electrical installations or services","Work in an area that may have a contaminated or flammable atmosphere","Tilt-up or precast concrete elements","Work on, in or adjacent to a road, railway, shipping lane or other traffic corridor in use by traffic other than pedestrians","Work in an area with movement of powered mobile plant","Work in areas with artificial extremes of temperature","Work in or near water or other liquid that involves a risk of drowning","Diving work"]
HEIGHT={
"ladder":[("Set up ladders / trestles","Fall from ladder or trestle; ladder slipping on uneven or wet ground","Ladders only for short, light work. Industrial-rated (150 kg), set at 4:1, footed or tied off, three points of contact, never working off the top two rungs. Trestles on firm level ground with planks secured. If the job needs long stints at height, switch to a mobile scaffold or EWP."),("Paint at height","Overreaching; dropped tins and tools onto people below","Move the ladder rather than reaching past the stiles. Tins on hooks or in trays. Barricade and sign the area underneath.")],
"scaffold":[("Erect mobile scaffold","Fall from platform edge; scaffold tipping on soft or sloping ground","Erected to manufacturer's instructions with guardrails, mid-rails and toeboards on all open sides. Castors locked before anyone climbs. Platform over 4 m erected by a licensed scaffolder. Ground checked for soft spots and slope."),("Paint from scaffold / move scaffold","Scaffold moved with someone on it; contact with overhead obstructions; dropped objects","Never move the scaffold with anyone on it; check overhead before moving. Tins on hooks or in trays. Barricade and sign the area underneath.")],
"ewp":[("Pre-start and set up EWP","Tip-over on soft or sloping ground; defective machine","Daily pre-start check done and recorded. Ground checked for soft spots, slopes and pits; outriggers on pads. Operator holds a WP high risk work licence for booms 11 m or more, or documented training for other EWPs."),("Paint from EWP basket","Crush between basket and structure; ejection from basket; dropped objects","Harness and short lanyard clipped to the basket anchor on boom lifts. Spotter on the ground near structures. Written rescue plan and ground person knows the lower controls. Exclusion zone below.")],
"none":[("Confirm no work at height","Unplanned work at height during the job","No access equipment planned. If any work over 2 m (3 m in some states) comes up, stop and update this SWMS before starting it.")]}
EXTRA={
"power":("Work near overhead powerlines or energised services",[("Painting fascias, eaves and gutters near the point of attachment","Electric shock from contact with overhead service lines or energised fittings","Before starting, identify all overhead lines and confirm the network operator's approach distances for your state. Request de-energising or tiger tails (line covers) from the network operator where approach distances cannot be kept. Non-conductive (fibreglass) ladders only. Light fittings and outlets on surfaces being prepared are isolated by a licensed electrician or masked without removal.")]),
"old":("Surface preparation on a pre-1990 building",[("Sanding, scraping or pressure-washing eaves, sheet cladding and ceilings","Disturbing asbestos-containing material (e.g. fibro sheeting); lead dust from old paint","Ask the client/PC for the asbestos register or inspection report before starting prep. If material is suspected and not tested, STOP: do not sand, drill, scrape or pressure-wash it until it is sampled. Removal or disturbance done only by appropriately licensed removalists as required. For old lead paint: wet scraping, no dry sanding or burning off without controls, drop sheets, vacuum with a HEPA filter, wash hands before eating.")]),
"road":("Work next to a road or traffic",[("Painting front fences, facades and boundary walls","Being struck by vehicles; vehicles striking ladders or scaffold","Where work is on or adjacent to a road, a traffic management plan is in place, prepared by an appropriately qualified person where the road authority requires it. Hi-vis worn. Barriers and signage set out before work starts. Ladders and scaffold kept out of the trafficable area.")])}
REVIEW="Review this SWMS when control measures change, when work is not being done in accordance with it, after an incident or near miss, when site conditions change, or when a worker or HSR raises a concern. If work is not following the SWMS, stop the work until it can be done in accordance with it."
NOTE="Work must be performed in accordance with this SWMS. It must be kept and available for inspection until the high risk construction work is completed. If revised, keep all versions. If a notifiable incident occurs, keep it for at least 2 years from the date of the incident."
def disclaimer(state):
    vic=" Victoria operates under the OHS Act and Regulations." if state=="VIC" else ""
    return f"Template tool only, not legal advice. A generic SWMS may not meet WHS laws unless it is reviewed for the specific workplace and amended (Safe Work Australia). Tailor it to the site, consult your workers, and check the {state} regulator's requirements.{vic} Source: Safe Work Australia SWMS information sheet and Model Code of Practice: Construction Work (2024)."
def build(a):
    tick=set()
    if a["height"]!="none": tick.add(0)
    if a["old"]=="y": tick.add(3)
    if a["power"]=="y": tick.add(10)
    if a["road"]=="y": tick.add(13)
    if a["height"]=="ewp": tick.add(14)
    secs=[("Work at height",HEIGHT[a["height"]],True)]
    for k in ("power","old","road"):
        if a[k]=="y": secs.append((EXTRA[k][0],EXTRA[k][1],False))
    return tick,secs
